import fs from 'node:fs';
import path from 'node:path';

const KEY_RE = /^[A-Za-z0-9_.-]+$/;

export function isValidKey(key) {
  return typeof key === 'string' && KEY_RE.test(key);
}

export function loadStore(filePath) {
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return {};
    throw err;
  }
  if (text.trim() === '') return {};
  const data = JSON.parse(text);
  if (data === null || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error(`invalid store format in ${filePath}`);
  }
  return data;
}

export function saveStore(filePath, store) {
  const abs = path.resolve(filePath);
  const dir = path.dirname(abs);
  fs.mkdirSync(dir, { recursive: true });
  const tmp = path.join(
    dir,
    `.${path.basename(abs)}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}.tmp`
  );
  try {
    fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
    fs.renameSync(tmp, abs);
  } catch (err) {
    try { fs.unlinkSync(tmp); } catch { /* ignore */ }
    throw err;
  }
}

export function isExpired(record, now = Date.now()) {
  return record != null && record.expiresAt != null && record.expiresAt <= now;
}
